        budget: { $ref: '#/$defs/GoalBudget' },
        completed: { type: 'boolean' },
        consumed_tokens: { minimum: 0, type: 'integer', maximum: 9007199254740991 },
        consumed_turns: { minimum: 0, type: 'integer', maximum: 9007199254740991 },
        latest_check_model_step: { anyOf: [{ $ref: '#/$defs/ModelStepId' }, { type: 'null' }] },
        revision: { $ref: '#/$defs/Revision' },
        turn_task_id: { $ref: '#/$defs/TurnTaskId' },
