        mcp_consent: {
          anyOf: [{ $ref: '#/$defs/McpTurnConsentRef' }, { type: 'null' }],
          description: 'A ReadOnly answer covering one MCP server for the rest of the turn.',
        },
        memory_consent: { anyOf: [{ $ref: '#/$defs/MemorySessionConsentRef' }, { type: 'null' }] },
        network_consent: {
          anyOf: [{ $ref: '#/$defs/NetworkSessionConsentRef' }, { type: 'null' }],
        },
        operation_fingerprint: { $ref: '#/$defs/CanonicalSha256HashV1' },
        profile: { $ref: '#/$defs/SecurityProfile' },
